#!/usr/bin/env python3
"""Generate built-in cluster scopes and Argo API groups from pinned API types.

The extension APIs use the same release as k8s.io/api. These are generation
inputs only; C4 uses no discovery client or additional runtime dependency.
Run from the repository root with GOTMPDIR outside the RAM-backed temp dir.
"""
import argparse
import json
from pathlib import Path
import re
import subprocess


def module_source(module):
    return Path(json.loads(subprocess.check_output(
        ["go", "mod", "download", "-json", module], text=True))["Dir"])


def generate():
    version = re.search(r"k8s.io/api (v\S+)", Path("go.mod").read_text())[1]
    modules = ["k8s.io/api", "k8s.io/apiextensions-apiserver", "k8s.io/kube-aggregator"]
    kinds = set()
    for module in modules:
        root = module_source(module + "@" + version)
        for source in root.rglob("types.go"):
            register = source.with_name("register.go")
            if not register.exists():
                continue
            group = re.search(r'GroupName\s*=\s*"([^"]*)"', register.read_text())
            if not group:
                continue
            declarations = re.finditer(r"((?:(?://[^\n]*)?\n)+)type (\w+) struct", source.read_text())
            for declaration in declarations:
                if "+genclient:nonNamespaced" in declaration[1]:
                    kinds.add((group[1], declaration[2]))
    rows = "\n".join(f'\t\t"{group}/{kind}",' for group, kind in sorted(kinds))
    return f'''// Code generated by testdata/generate_scopes.py from Kubernetes {version} API types; DO NOT EDIT.

package argoworkflow

import (
    "slices"
    "k8s.io/apimachinery/pkg/runtime/schema"
)

// Version-independent scopes come from the API's genclient:nonNamespaced markers.
func clusterScopedKind(kind ResourceKind) bool {{
    gv, _ := schema.ParseGroupVersion(kind.APIVersion)
    return slices.Contains(clusterScopedKinds(), gv.Group+"/"+kind.Kind)
}}

func clusterScopedKinds() []string {{
    return []string{{
{rows}
    }}
}}
'''


def generate_workloads():
    modules = ["github.com/argoproj/argo-workflows/v4", "github.com/argoproj/argo-events"]
    groups = {}
    for module in modules:
        version = re.search(re.escape(module) + r" (v\S+)", Path("go.mod").read_text())[1]
        root = module_source(module + "@" + version)
        for register in (root / "pkg/apis").rglob("register.go"):
            doc = register.with_name("doc.go")
            if not doc.exists():
                continue
            group = re.search(r"\+groupName=(\S+)", doc.read_text())
            known = re.search(r"scheme.AddKnownTypes\(SchemeGroupVersion,(.*?)\n\s*\)", register.read_text(), re.S)
            if not group or not known:
                continue
            kinds = re.findall(r"&(\w+)\{\}", known[1])
            groups.setdefault(group[1], set()).update(k for k in kinds if not k.endswith("List"))
    if not groups:
        raise ValueError("no registered Argo API types found")
    rows = "\n".join('\t\t"' + group + '": {' + ', '.join('"' + k + '"' for k in sorted(kinds)) + '},'
                     for group, kinds in sorted(groups.items()))
    return f'''// Code generated by testdata/generate_scopes.py from pinned Argo API registration; DO NOT EDIT.

package argoworkflow

import "k8s.io/apimachinery/pkg/runtime/schema"

func argoWorkloadKind(kind ResourceKind) bool {{
    gv, _ := schema.ParseGroupVersion(kind.APIVersion)
    _, refused := argoAPIKinds()[gv.Group]
    return refused
}}

func argoAPIKinds() map[string][]string {{
    return map[string][]string{{
{rows}
    }}
}}
'''


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for name, source in [("cluster_scopes.go", generate()), ("argo_api_kinds.go", generate_workloads())]:
        formatted = subprocess.check_output(["gofmt"], input=source, text=True)
        output = Path("pkg/argoworkflow") / name
        if args.check:
            if output.read_text() != formatted:
                raise SystemExit(name + " differs from the pinned API types")
        else:
            output.write_text(formatted)
